from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v20b
from taf.selenium.sbts.common.exceptions import VersionNotSupport


class RndMode(v20b.RndMode):
    def __init__(self, driver, download_checker):
        super(RndMode, self).__init__(driver, download_checker)
        self._fiveg_performance_test = NrPerformanceTestPage(driver)

    @property
    def fiveg_performance_test(self):
        return self._fiveg_performance_test


class NrPerformanceTestPage(v20b.rnd_mode.NrPerformanceTestPage):
    _MENU_ROUTE_LIST = ['R&D Mode', 'NR Performance Test']

    def __init__(self, driver):
        super(NrPerformanceTestPage, self).__init__(driver)
        self._view_panel = NrPerformanceTestPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def get_carrier_frequency(self, timeout):
        raise VersionNotSupport("This functions is supported under this version.")

    def start_pucch_test(self, *args, **kwargs):
        self._view_panel.start_pucch_test(*args, **kwargs)

    def start_prach_test(self, *args, **kwargs):
        self._view_panel.start_prach_test(*args, **kwargs)

    def start_pusch_test(self, *args, **kwargs):
        self._view_panel.start_pusch_test(*args, **kwargs)


class NrPerformanceTestPageViewPanel(v20b.rnd_mode.NrPerformanceTestPageViewPanel):
    _param_root_xpath = '//div[contains(text(), "{}")]/parent::*'
    _param_xpath = {
        'nrarfcn_downlink': _param_root_xpath.format('NRARFCN downlink:'),
        'nrarfcn_uplink': _param_root_xpath.format('NRARFCN uplink:'),
        'nrarfcn': _param_root_xpath.format('NRARFCN:'),
    }

    def __init__(self, driver):
        super(NrPerformanceTestPageViewPanel, self).__init__(driver)

    def _configure_nrarfcn(self, timeout):
        value = getattr(self, 'nrarfcn_downlink')
        if value is not None:
            self.insert_text_to_enable_element((By.XPATH, self._param_xpath['nrarfcn_downlink'] + '//input'),
                                               value,
                                               timeout)
        value = getattr(self, 'nrarfcn_uplink')
        if value is not None:
            self.insert_text_to_enable_element((By.XPATH, self._param_xpath['nrarfcn_uplink'] + '//input'),
                                               value,
                                               timeout)

        value = getattr(self, 'nrarfcn')
        if value is not None:
            self.insert_text_to_enable_element((By.XPATH, self._param_xpath['nrarfcn'] + '//input'),
                                               value,
                                               timeout)

    def _configure_pfa_target(self):
        _PFA_TARGET_LIST_BUTTON_XPATH = '//div[contains(text(), "Probability false alarm")]/parent::*//button'
        _PFA_TARGET_LIST_OPTIONS_XPATH = '//div[contains(text(), "Probability false alarm")]/parent::*//ul//li'
        pfa_target = getattr(self, 'pfa_target', None)
        if pfa_target:
            self.select_element_from_dropdown_list_by_text_and_click(
                pfa_target,
                (By.XPATH, _PFA_TARGET_LIST_BUTTON_XPATH),
                (By.XPATH, _PFA_TARGET_LIST_OPTIONS_XPATH))

    def _configure_prach_config_index(self):
        prach_config_index = getattr(self, 'prach_config_index', None)
        if prach_config_index is not None:
            self.insert_text_to_enable_element(
                (By.XPATH, self._param_root_xpath.format('PRACH configuration index') + '//input'),
                prach_config_index)

    def _basic_configure(self, params, timeout):
        super(NrPerformanceTestPageViewPanel, self)._basic_configure(params, timeout)
        self._configure_nrarfcn(timeout)
        self._configure_pfa_target()
        self._configure_prach_config_index()

    def start_pucch_test(self, local_cell, rep_time_int=None, reception_slot=None, expectation_slot=None,
                         beam_id=None, ru_mode=None, physical_cell_id=None, pucch_format=None, prb_offset=None,
                         number_of_pucch_symbol=None, largest_prb_index=None, pucch_payload_content=None,
                         nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None, timeout=10):
        setattr(self, 'nrarfcn_downlink', nrarfcn_downlink)
        setattr(self, 'nrarfcn_uplink', nrarfcn_uplink)
        setattr(self, 'nrarfcn', nrarfcn)
        super(NrPerformanceTestPageViewPanel, self).start_pucch_test(local_cell=local_cell,
                                                                     rep_time_int=rep_time_int,
                                                                     reception_slot=reception_slot,
                                                                     expectation_slot=expectation_slot,
                                                                     beam_id=beam_id,
                                                                     ru_mode=ru_mode,
                                                                     physical_cell_id=physical_cell_id,
                                                                     pucch_format=pucch_format,
                                                                     prb_offset=prb_offset,
                                                                     number_of_pucch_symbol=number_of_pucch_symbol,
                                                                     largest_prb_index=largest_prb_index,
                                                                     pucch_payload_content=pucch_payload_content,
                                                                     timeout=int(timeout))

    def _setup_common_params(self, *args, **kwargs):
        super(NrPerformanceTestPageViewPanel, self)._setup_common_params(*args, **kwargs)
        self._configure_nrarfcn(kwargs['timeout'])

    def start_prach_test(self, local_cell, rep_time_int, reception_slot=None, expectation_slot=None,
                         beam_id=None, ru_mode=None, physical_cell_id=None, preamble_index=None,
                         accepted_timing_error=None, constant_offset=None, delay_pattern_duration=None,
                         prach_format=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None,
                         pfa_target=None, prach_config_index=None, timeout=10):
        setattr(self, 'nrarfcn_downlink', nrarfcn_downlink)
        setattr(self, 'nrarfcn_uplink', nrarfcn_uplink)
        setattr(self, 'nrarfcn', nrarfcn)
        setattr(self, 'pfa_target', pfa_target)
        setattr(self, 'prach_config_index', prach_config_index)
        timeout = int(timeout)
        super(NrPerformanceTestPageViewPanel, self).start_prach_test(local_cell=local_cell,
                                                                     rep_time_int=rep_time_int,
                                                                     reception_slot=reception_slot,
                                                                     expectation_slot=expectation_slot,
                                                                     beam_id=beam_id,
                                                                     ru_mode=ru_mode,
                                                                     physical_cell_id=physical_cell_id,
                                                                     preamble_index=preamble_index,
                                                                     accepted_timing_error=accepted_timing_error,
                                                                     constant_offset=constant_offset,
                                                                     delay_pattern_duration=delay_pattern_duration,
                                                                     prach_format=prach_format,
                                                                     timeout=timeout)

    def start_pusch_test(self, local_cell, frc_index, do_rate, do_type, rep_time_int,
                         beam_id=None, ru_mode=None, physical_cell_id=None, bb_selector=None,
                         prb_offset=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None, timeout=15):
        setattr(self, 'nrarfcn_downlink', nrarfcn_downlink)
        setattr(self, 'nrarfcn_uplink', nrarfcn_uplink)
        setattr(self, 'nrarfcn', nrarfcn)
        super(NrPerformanceTestPageViewPanel, self).start_pusch_test(local_cell=local_cell,
                                                                     frc_index=frc_index,
                                                                     do_rate=do_rate,
                                                                     do_type=do_type,
                                                                     rep_time_int=rep_time_int,
                                                                     beam_id=beam_id,
                                                                     ru_mode=ru_mode,
                                                                     physical_cell_id=physical_cell_id,
                                                                     bb_selector=bb_selector,
                                                                     prb_offset=prb_offset,
                                                                     timeout=int(timeout))
